// Poster text, generated by rules from the computed GeoAI figures (never free-written numbers).
// Every sentence below is a template filled from the analysis; zeros are printed as zeros.
import { fmt } from "./poster-kit";

export type PosterAnalysis = {
  name: string; areaKm2: number;
  flood: { highPct: number; streamPct: number; waterPct: number; exposedPct: number; moderatePct: number; lowPct: number; exposedKm2: number; moderateKm2: number };
  terrain: { meanSlopeDeg: number; steepPct: number; flatPct: number };
  assets: { schools: { total: number; high: number; moderate: number }; health: { total: number; high: number; moderate: number }; markets: { total: number; high: number; moderate: number } };
  roads: { totalKm: number; exposedKm: number; majorKm: number; majorExposedKm: number };
  rank: { position: number; of: number; exposureIndex: number };
  safeSites: { name: string; lon: number; lat: number; meanSlopeDeg: number; nearestRoadKm: number; nearestMarketKm: number; nearestSchoolKm: number; nearestHealthKm: number }[];
  generatedAt: string;
};
export type RankRow = { rank: number; name: string; exposureIndex: number; exposedPct: number };

const plural = (n: number, one: string, many = one + "s") => `${fmt(n, 0)} ${n === 1 ? one : many}`;
const median = (a: number[]) => { const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length ? (s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2) : 0; };

export function posterContent(a: PosterAnalysis, ranking: RankRow[]) {
  const f = a.flood, t = a.terrain, as = a.assets, rd = a.roads, rk = a.rank;
  const med = median(ranking.map(r => r.exposedPct));
  const tier = rk.position <= 10 ? "high" : rk.position > rk.of - 10 ? "low" : "mid";
  const tierText = tier === "high" ? `among the ${10} most flood-exposed LGAs in Osun` : tier === "low" ? `among the ${10} least flood-exposed LGAs in Osun` : "in the middle of the Osun LGA ranking";
  const nFac = as.schools.total + as.health.total + as.markets.total;
  const facHigh = as.schools.high + as.health.high + as.markets.high;

  const headline = `${fmt(f.exposedPct)}% of ${a.name} LGA sits in flood-susceptible zones.`;
  const tagline = "Know your plot before you buy.";

  const conclusions: string[] = [];
  conclusions.push(`${fmt(f.exposedPct)}% of ${a.name} LGA (${fmt(f.exposedKm2)} of ${fmt(a.areaKm2)} km²) is in High-susceptibility zones and ${fmt(f.moderatePct)}% is Moderate. It ranks ${rk.position} of ${rk.of} on exposure (1 = most exposed; index ${fmt(rk.exposureIndex)}), ${tierText}. The state median share in High zones is ${fmt(med)}%.`);
  conclusions.push(nFac === 0
    ? "No schools, health facilities or markets are on record for this LGA (0), so facility exposure cannot yet be measured. Field mapping is the first step."
    : (() => {
      const parts = [["health facilities", as.health], ["markets", as.markets], ["schools", as.schools]].filter(([, t]: any) => t.total > 0).map(([n, t]: any) => `${t.high} of ${t.total} ${n}`);
      const none = [["schools", as.schools], ["health facilities", as.health], ["markets", as.markets]].filter(([, t]: any) => t.total === 0).map(([n]: any) => n);
      return `Of the facilities on record, ${parts.join(", ").replace(/, ([^,]*)$/, " and $1")} lie in High zones.${none.length ? ` No ${none.join(" or ")} are on record (0).` : ""}`;
    })());
  if (rd.totalKm > 0) conclusions.push(`${fmt(rd.exposedKm)} km (${fmt((rd.exposedKm / rd.totalKm) * 100, 0)}%) of the ${fmt(rd.totalKm, 0)} km road network crosses High zones, including ${fmt(rd.majorExposedKm)} km of ${fmt(rd.majorKm, 0)} km of major road: the routes for supplies and evacuation.`);
  conclusions.push(t.flatPct >= 15
    ? `Mean slope is ${fmt(t.meanSlopeDeg)}° and ${fmt(t.flatPct)}% of the LGA is flat (below 2°). Flat, low-lying ground drains slowly, so floodwater collects there.`
    : t.steepPct >= 10
      ? `Mean slope is ${fmt(t.meanSlopeDeg)}° and ${fmt(t.steepPct)}% of the LGA is steep (10° or more). Steep ground sheds water quickly towards valley floors.`
      : `Terrain is gentle (mean slope ${fmt(t.meanSlopeDeg)}°); susceptibility follows the valleys and modelled streams.`);
  conclusions.push(a.safeSites.length
    ? `${plural(a.safeSites.length, "candidate site")} on Low-susceptibility ground (gentle slope, within 1 km of a road) ${a.safeSites.length === 1 ? "was" : "were"} identified.`
    : "No Low-susceptibility block met the slope and road-access criteria, so detailed site investigation is advised before building.");

  const recs: string[] = [];
  recs.push(`Field-map the LGA. On record today: ${plural(as.schools.total, "school")}, ${plural(as.health.total, "health facility", "health facilities")} and ${plural(as.markets.total, "market")}. GeoEstate can complete the inventory with a GPS survey of facilities, drains and past flood points.`);
  recs.push(f.exposedPct >= med
    ? `Prioritise drainage clearing and no-build buffers along the modelled streams and High zones (${fmt(f.exposedKm2)} km²).`
    : `Protect natural channels and keep drains clear: ${fmt(f.exposedKm2)} km² is still in High zones.`);
  if (facHigh > 0) {
    const bits = [as.health.high && plural(as.health.high, "health facility", "health facilities"), as.schools.high && plural(as.schools.high, "school"), as.markets.high && plural(as.markets.high, "market")].filter(Boolean);
    recs.push(`Flood-proof or plan safe access for the ${bits.join(", ").replace(/, ([^,]*)$/, " and $1")} in High zones (raise floors, protect power and water, agree evacuation routes).`);
  } else recs.push("Use the zone map to site new clinics, schools and markets outside High zones.");
  if (rd.majorExposedKm > 0) recs.push(`Raise roads or add culverts on the ${fmt(rd.majorExposedKm)} km of major road in High zones.`);
  else if (rd.exposedKm > 0) recs.push(`Improve drainage on the ${fmt(rd.exposedKm)} km of local roads in High zones.`);
  recs.push(a.safeSites.length
    ? `Steer new housing to the ${a.safeSites.length} candidate safer ${a.safeSites.length === 1 ? "site" : "sites"}, and run a GeoEstate LandCheck on every plot before purchase.`
    : "Run a GeoEstate LandCheck and an on-site drainage survey before buying or building here.");

  const intro = `Floods damage homes, roads, clinics and livelihoods across Osun, yet land and infrastructure decisions are often made without a map of where water collects. This poster applies GeoEstate GeoAI to ${a.name} LGA: terrain, drainage, satellite water evidence and mapped facilities show where susceptibility is highest and what sits inside it, to help planners, investors and communities build and buy on safer ground.`;
  return { headline, tagline, conclusions, recs, intro, med, tier };
}

export const SOURCES = [
  ["Terrain & drainage", "ALOS 30 m elevation model (height above drainage, wetness, relief)"],
  ["Observed water", "JRC surface water, Global Flood Database, Sentinel-1 radar"],
  ["Land cover", "ESA WorldCover 2021, 10 m"],
  ["Facilities", "GRID3 health facilities v3; HOT/OSM education; Markets in Nigeria"],
  ["Roads", "National road dataset (OSM-derived)"],
  ["Boundaries", "geoBoundaries ADM1 / ADM2"],
];
export const METHOD = [
  ["Model the terrain", "Derive streams, height above drainage, wetness and relief from the elevation model."],
  ["Score susceptibility", "Combine them into a 0-100 score; add satellite water evidence. Low < 35, Moderate 35-64, High 65+."],
  ["Overlay assets", "Intersect schools, health facilities, markets and roads with the zones, per LGA."],
  ["Rank and advise", "Exposure index: 40% area, 40% facilities, 20% roads in High zones. Find safer candidate sites."],
];
export const DISCLAIMER = "Terrain-based flood susceptibility, not a flood-risk determination. It does not use rainfall, drainage works or blocked channels. Facility data are incomplete and counts show what is on record today; field mapping is under way. Validate before formal use.";
